  const w = m[3];
  let x;
  if (!w) work = '';
  else if ((x = /^(\w+) sets? of papers to mark, (\w+) ready to hand back\.$/i.exec(w))) work = zhN(x[1]) + ' 批作業待批改，' + zhN(x[2]) + ' 批可以發還。';
  else if ((x = /^(\w+) sets? of papers to mark\.$/i.exec(w))) work = zhN(x[1]) + ' 批作業待批改。';
